#define _POSIX_C_SOURCE 200809L
#include "protocol.h"
#include <openssl/crypto.h>
#include <stdio.h>
#include <string.h>
#include <stdlib.h>
#include <time.h>
#include <errno.h>
#include <unistd.h>
#include <fcntl.h>
#include <sys/stat.h>

double pc_clock(void) { struct timespec t; clock_gettime(CLOCK_MONOTONIC,&t); return t.tv_sec*1000.0+t.tv_nsec/1e6; }
static unsigned depth(unsigned n) { unsigned d=0; while(n>1){n=(n+1)/2;d++;}return d; }
unsigned pc_total(unsigned n) { unsigned t=0; if(n<2||n>1024)return 0;while(n>1){t+=n;n=(n+1)/2;}return t; }
int pc_id(unsigned n,unsigned l,unsigned i,unsigned *id) { unsigned off=0;if(!pc_total(n))return 0;while(l--){off+=n;n=(n+1)/2;if(n==1)return 0;}if(i>=n)return 0;*id=off+i;return 1; }
static void put32(unsigned char *p,unsigned n){p[0]=n>>24;p[1]=n>>16;p[2]=n>>8;p[3]=n;}
static unsigned get32(const unsigned char *p){return ((unsigned)p[0]<<24)|((unsigned)p[1]<<16)|((unsigned)p[2]<<8)|p[3];}
static size_t var(unsigned n,unsigned char *p){size_t k=0;do{p[k++]=(n&127)|(n>=128?128:0);n>>=7;}while(n);return k;}
static int readvar(const unsigned char *p,size_t n,size_t *off,unsigned *v){unsigned x=0;size_t begin=*off;unsigned char canonical[3];for(unsigned shift=0;shift<=14;shift+=7){unsigned b;if(*off>=n)return 0;b=p[(*off)++];x|=(b&127)<<shift;if(!(b&128)){if(x>65535||var(x,canonical)!=*off-begin||memcmp(canonical,p+begin,*off-begin))return 0;*v=x;return 1;}}return 0;}
static int find(const PcCache *c,unsigned id){for(unsigned i=0;i<c->count;i++)if(c->nodes[i].id==id)return (int)i;return -1;}
static void touch(PcCache *c,unsigned at){PcNode v=c->nodes[at];memmove(c->nodes+at,c->nodes+at+1,(c->count-at-1)*sizeof(v));c->nodes[c->count-1]=v;}
int pc_encode(const PcCache *c,unsigned char *out,size_t cap,size_t *len){unsigned char selected[PC_MAX]={0},body[PC_WIRE];unsigned runs=0,total=pc_total(c->tree.leaves);size_t b=0,o=38;if(!total||c->count>total||cap<PC_WIRE)return 0;for(unsigned i=0;i<c->count;i++){unsigned id=c->nodes[i].id;if(id>=total||selected[id])return 0;selected[id]=1;}for(unsigned i=0;i<total;){if(!selected[i]){i++;continue;}unsigned start=i;while(i<total&&selected[i])i++;b+=var(start,body+b);b+=var(i-start,body+b);runs++;}memcpy(out,"PCA2\1\4",6);memcpy(out+6,c->tree.root.bytes,32);o+=var(c->tree.leaves,out+o);o+=var(runs,out+o);if(o+b>cap)return 0;memcpy(out+o,body,b);*len=o+b;return 1;}
int pc_decode(const unsigned char *in,size_t len,const MTRoot *tree,unsigned char available[PC_MAX]){size_t o=38;unsigned n,r,start,size,end=0,total=pc_total(tree->leaves);if(!total||len<40||len>PC_WIRE||memcmp(in,"PCA2\1\4",6)||CRYPTO_memcmp(in+6,tree->root.bytes,32))return 0;if(!readvar(in,len,&o,&n)||n!=tree->leaves||!readvar(in,len,&o,&r)||r>total)return 0;memset(available,0,PC_MAX);for(unsigned j=0;j<r;j++){if(!readvar(in,len,&o,&start)||!readvar(in,len,&o,&size)||!size||start>=total||size>total-start||(j&&start<=end))return 0;end=start+size;memset(available+start,1,size);}return o==len;}
int pc_partial(const MTProof *p,const unsigned char available[PC_MAX],unsigned char *out,size_t cap,size_t *len,PcMetrics *m){unsigned pos=p->index,width=p->tree.leaves,d=depth(width),bl=(d+7)/8;size_t o=46+bl;double start=pc_clock();if(!pc_total(width)||pos>=width||d!=p->depth||cap<o+32*d)return 0;memcpy(out,"MTP2",4);put32(out+4,width);put32(out+8,pos);memcpy(out+12,p->tree.root.bytes,32);out[44]=d;out[45]=bl;memset(out+46,0,bl);m->normal=d;m->sent=0;m->range_ms=0;for(unsigned l=0;l<d;l++){unsigned id,sibling=pos&1?pos-1:(pos+1<width?pos+1:width-1);double t=pc_clock();if(!pc_id(p->tree.leaves,l,sibling,&id))return 0;int has=available[id];m->range_ms+=pc_clock()-t;if(!has){out[46+l/8]|=1<<(7-l%8);memcpy(out+o,p->siblings[l].bytes,32);o+=32;m->sent++;}pos/=2;width=(width+1)/2;}m->reused=d-m->sent;m->proof_bytes=o;m->construct_ms=pc_clock()-start;*len=o;return 1;}
int pc_reconstruct(const unsigned char *in,size_t len,const PcCache *c,MTProof *p,PcMetrics *m){double start=pc_clock();unsigned n,pos,d,bl,width;size_t o;if(len<46||memcmp(in,"MTP2",4))return 0;n=get32(in+4);pos=get32(in+8);d=in[44];bl=in[45];if(n!=c->tree.leaves||!pc_total(n)||pos>=n||d!=depth(n)||bl!=(d+7)/8||len<46+bl||CRYPTO_memcmp(in+12,c->tree.root.bytes,32))return 0;if(d%8&&(in[45+bl]&((1<<(8-d%8))-1)))return 0;p->tree=c->tree;p->index=pos;p->depth=d;width=n;o=46+bl;m->normal=d;m->sent=0;m->lookup_ms=0;for(unsigned l=0;l<d;l++){if(in[46+l/8]&(1<<(7-l%8))){if(o+32>len)return 0;memcpy(p->siblings[l].bytes,in+o,32);o+=32;m->sent++;}else{unsigned id,sibling=pos&1?pos-1:(pos+1<width?pos+1:width-1);double t=pc_clock();if(!pc_id(n,l,sibling,&id))return 0;int at=find(c,id);m->lookup_ms+=pc_clock()-t;if(at<0)return 0;p->siblings[l]=c->nodes[at].hash;}pos/=2;width=(width+1)/2;}m->reused=d-m->sent;m->proof_bytes=len;m->reconstruct_ms=pc_clock()-start;return o==len;}
static int insert(PcCache *c,unsigned id,MerkleHash hash,PcMetrics *m){int at=find(c,id);if(at>=0){if(CRYPTO_memcmp(c->nodes[at].hash.bytes,hash.bytes,32))return 0;if(!c->policy)touch(c,(unsigned)at);}else{if(c->count>=PC_MAX)return 0;c->nodes[c->count++]=(PcNode){id,hash};m->added++;}return 1;}
int pc_learn(PcCache *c,const unsigned char *credential,size_t len,const MTProof *p,PcMetrics *m){unsigned pos=p->index,width=p->tree.leaves,id;MerkleHash current,next;double t=pc_clock();if(!mt_proof_verify(credential,len,p,&c->tree))return 0;m->verify_ms+=pc_clock()-t;if(!merkle_leaf_hash(credential,len,&current))return 0;m->hits=m->misses=m->added=m->evicted=0;for(unsigned l=0;l<p->depth;l++){unsigned sibling=pos&1?pos-1:(pos+1<width?pos+1:width-1);if(!pc_id(width==p->tree.leaves?width:p->tree.leaves,l,sibling,&id))return 0;int at=find(c,id);if(at>=0){m->hits++;if(!c->policy)touch(c,(unsigned)at);}else m->misses++;pos/=2;width=(width+1)/2;}pos=p->index;width=p->tree.leaves;if(!pc_id(width,0,pos,&id)||!insert(c,id,current,m))return 0;for(unsigned l=0;l<p->depth;l++){unsigned sibling=pos&1?pos-1:(pos+1<width?pos+1:width-1);if(!pc_id(p->tree.leaves,l,sibling,&id)||!insert(c,id,p->siblings[l],m))return 0;if(!(pos&1)?!merkle_parent_hash(&current,&p->siblings[l],&next):!merkle_parent_hash(&p->siblings[l],&current,&next))return 0;current=next;pos/=2;width=(width+1)/2;if(l+1<p->depth&&(!pc_id(p->tree.leaves,l+1,pos,&id)||!insert(c,id,current,m)))return 0;}while(c->count>c->budget/69){unsigned victim=0;if(c->policy){/* level-major id ordering: select lowest level, retain insertion tie order */unsigned minlevel=99;for(unsigned k=0;k<c->count;k++){unsigned w=c->tree.leaves,off=0,l=0;while(c->nodes[k].id>=off+w){off+=w;w=(w+1)/2;l++;}if(l<minlevel){minlevel=l;victim=k;}}}memmove(c->nodes+victim,c->nodes+victim+1,(--c->count-victim)*sizeof(PcNode));m->evicted++;}m->cache_nodes=c->count;m->cache_bytes=c->count*69;return 1;}
/* Private local persistence: immutable root/config binding, LRU order retained.
   Authentication of a loaded value still requires the next proof to reach root. */
int pc_load(PcCache *c,const char *file){unsigned char data[PC_WIRE*12];size_t n;struct stat st;if(lstat(file,&st)){return errno==ENOENT;}if(!S_ISREG(st.st_mode)||(st.st_mode&077)||st.st_uid!=geteuid()||!mt_read_file(file,data,sizeof(data),&n)||n<49||memcmp(data,"PCS1",4)||get32(data+4)!=c->tree.leaves||CRYPTO_memcmp(data+8,c->tree.root.bytes,32)||get32(data+40)!=c->budget||data[44]!=c->policy)return 0;unsigned count=get32(data+45);if(count>pc_total(c->tree.leaves)||count>c->budget/69||n!=49+count*36)return 0;unsigned char seen[PC_MAX]={0};for(unsigned i=0;i<count;i++){unsigned id=get32(data+49+i*36);if(id>=pc_total(c->tree.leaves)||seen[id])return 0;seen[id]=1;c->nodes[i].id=id;memcpy(c->nodes[i].hash.bytes,data+53+i*36,32);}c->count=count;return 1;}
int pc_save(const PcCache *c,const char *file){unsigned char data[49+PC_MAX*36];char temp[4096];size_t n=49+c->count*36;int fd,ok=1;memcpy(data,"PCS1",4);put32(data+4,c->tree.leaves);memcpy(data+8,c->tree.root.bytes,32);put32(data+40,c->budget);data[44]=c->policy;put32(data+45,c->count);for(unsigned i=0;i<c->count;i++){put32(data+49+i*36,c->nodes[i].id);memcpy(data+53+i*36,c->nodes[i].hash.bytes,32);}if(snprintf(temp,sizeof(temp),"%s.tmp.XXXXXX",file)>=(int)sizeof(temp))return 0;fd=mkstemp(temp);if(fd<0)return 0;for(size_t o=0;o<n;){ssize_t k=write(fd,data+o,n-o);if(k<=0){ok=0;break;}o+=(size_t)k;}if(fsync(fd))ok=0;if(close(fd))ok=0;if(ok&&rename(temp,file))ok=0;if(!ok)unlink(temp);return ok;}
